import { LinearGradient } from 'expo-linear-gradient'
import Animated, {
	SharedValue,
	useAnimatedStyle,
	useSharedValue,
	interpolate,
	Extrapolate,
	useAnimatedScrollHandler,
	FadeOut,
	LinearTransition
} from 'react-native-reanimated'
import { ProjectGroupItemButton } from './ProjectGroupItemButton'
import { AnimatedFlatList } from '@/components'
import { HomeScreenProjectGroup } from '@/types'
import {
	NativeScrollEvent,
	NativeSyntheticEvent,
	RefreshControl
} from 'react-native'
import {
	FETCH_COUNT,
	PROJECT_LIST_OFFSET,
	SEARCH_BAR_HEIGHT
} from '@/constants'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { useEffect, useState } from 'react'

type ProjectListProps = {
	projectGroups: HomeScreenProjectGroup[]
	hasMore: boolean
	isLoadingMore: boolean
	isRefreshing: boolean
	onFetchMoreProjects: () => void
	onScroll: (event: NativeSyntheticEvent<NativeScrollEvent>) => void
	onRefresh: () => void
	listYPosition: SharedValue<number>
	parentScrollY: SharedValue<number>
	isShining: boolean
	isSearchBarOpen: boolean
}

export const ProjectGroupList = ({
	projectGroups,
	hasMore,
	isLoadingMore,
	isRefreshing,
	onFetchMoreProjects,
	onScroll,
	onRefresh,
	listYPosition,
	parentScrollY,
	isShining,
	isSearchBarOpen
}: ProjectListProps) => {
	const insets = useSafeAreaInsets()
	const { theme } = useTheme()

	const isEmpty = projectGroups.length === 0
	const scrollY = useSharedValue(0)
	const activeButtonId = useSharedValue<string | null>(null)
	const resetTriggerId = useSharedValue<string | null>(null)

	const scrollHandler = useAnimatedScrollHandler({
		onScroll: (event) => {
			scrollY.value = event.contentOffset.y
			if (parentScrollY) {
				parentScrollY.value = event.contentOffset.y
			}
		}
	})

	const listAppearStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: listYPosition.get() }]
	}))

	const gradientOpacityStyle = useAnimatedStyle(() => ({
		opacity: interpolate(scrollY.value, [0, 12], [0, 1], Extrapolate.CLAMP)
	}))

	const projectFadeStyle = {
		top: isSearchBarOpen ? 0 : -PROJECT_LIST_OFFSET
	}

	const projectListStyle = {
		marginTop: isSearchBarOpen ? 0 : -PROJECT_LIST_OFFSET,
		paddingTop: isSearchBarOpen ? 0 : PROJECT_LIST_OFFSET
	}

	const [currentOffset, setCurrentOffset] = useState(0)
	// HACK: This is a hack to get the progress view offset to work
	useEffect(() => {
		if (!isShining) {
			setCurrentOffset(isSearchBarOpen ? 0 : PROJECT_LIST_OFFSET)
		}
	}, [isShining, isSearchBarOpen])

	return (
		<Animated.View
			style={[styles.projectListContainer(theme), listAppearStyle]}
		>
			{!isEmpty && (
				<Animated.View
					style={[
						styles.projectListFade,
						projectFadeStyle,
						gradientOpacityStyle
					]}
				>
					<LinearGradient
						colors={[colors[theme].background, `${colors[theme].background}00`]}
						style={{ flex: 1 }}
					/>
				</Animated.View>
			)}
			<AnimatedFlatList
				onScroll={scrollHandler}
				data={projectGroups}
				itemLayoutAnimation={LinearTransition.duration(300)}
				keyExtractor={(item) => item.id}
				refreshControl={
					<RefreshControl
						refreshing={isRefreshing}
						onRefresh={onRefresh}
						progressViewOffset={currentOffset}
					/>
				}
				renderItem={({ item, index }) => (
					<Animated.View
						exiting={FadeOut.duration(300)}
						layout={LinearTransition.duration(300)}
					>
						<ProjectGroupItemButton
							item={item}
							index={index}
							listYPosition={listYPosition}
							activeButtonId={activeButtonId}
							resetTriggerId={resetTriggerId}
						/>
					</Animated.View>
				)}
				onEndReached={() => {
					if (hasMore && !isRefreshing && !isLoadingMore) {
						onFetchMoreProjects()
					}
				}}
				scrollEnabled={!isEmpty}
				onEndReachedThreshold={0.5}
				removeClippedSubviews
				showsVerticalScrollIndicator={false}
				initialNumToRender={FETCH_COUNT}
				maxToRenderPerBatch={FETCH_COUNT}
				windowSize={5}
				updateCellsBatchingPeriod={100}
				style={[styles.projectList, projectListStyle]}
				contentContainerStyle={[
					{
						paddingBottom: SEARCH_BAR_HEIGHT + insets.bottom,
						gap: 28
					}
				]}
			/>
		</Animated.View>
	)
}

const styles = defineStyles({
	projectListContainer: (theme: Theme) => ({
		flexGrow: 1,
		flex: 1,
		zIndex: 2,
		backgroundColor: colors[theme].background
	}),
	projectListFade: {
		height: 48,
		position: 'absolute',
		left: 0,
		right: 0,
		bottom: 0,
		zIndex: 3
	},
	projectList: {
		zIndex: 2
	}
})
